{"path": "formatter.mjs", "content": "import { resolveOptions } from './resolver.mjs';

export function formatValue(value, overrides = {}) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError('value must be a finite number');
  }
  const options = resolveOptions(overrides);
  const number = options.prefix + value.toFixed(options.precision);
  return options.unitLabel ? `${number} ${options.unitLabel}` : number;
}
